card{border-radius:16px;display:flex;flex-direction:column;align-items:flex-start;gap:4px;text-align:left;padding:14px;background:#1a1a1a}.v18-card b{color:white}.v18-card small{color:#888;text-transform:none}.v18-form{display:grid;grid-template-columns:150px 1fr;gap:10px;align-items:center;margin:10px 0}.v18-form input,.v18-form select,.v18-textarea{background:#070707;color:white;border:1px solid #3a3a3a;border-radius:10px;padding:10px;min-height:40px}.v18-textarea{width:100%;height:120px}.v18-notechips{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.v18-notechips span{background:rgba(0,255,204,.12);color:var(--accent);border:1px solid rgba(0,255,204,.25);padding:8px 11px;border-radius:999px;font-weight:900}.v18-muted{color:#aaa;font-size:.86rem}.v18-list{display:flex;flex-direction:column;gap:8px}.v18-list-row{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center;background:#1a1a1a;border:1px solid #303030;border-radius:14px;padding:12px}.v18-list-row small{display:block;color:#888;margin-top:4px}.v18-mixer{display:grid;grid-template-columns:120px 1fr;gap:12px;align-items:center}.v18-lead-sheet{background:#f7f2e8;color:#161616;border-radius:16px;padding:22px;font-family:Georgia,serif}.v18-lead-sheet h1{margin:0;color:#111;font-size:2rem}.v18-lead-sheet h2{margin:4px 0 12px;color:#555;font-size:1rem}.v18-lead-sheet h3{color:#111;border-bottom:1px solid #d4c8b6;padding-bottom:4px}.v18-chordline{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}.v18-chordline span{font-family:monospace;background:#111;color:#fff;border-radius:7px;padding:5px 8px}.v18-lead-sheet pre{white-space:pre-wrap;font-family:inherit;line-height:1.45}.v18-practice{text-align:center;padding:22px}.v18-practice .big-section{font-size:1rem;color:var(--solo);text-transform:uppercase;font-weight:950;letter-spacing:2px}.v18-practice .big-chord{font-size:clamp(3rem,10vw,8rem);font-weight:950;color:var(--accent);text-shadow:0 0 25px rgba(0,255,204,.35);margin:20px 0}.v18-practice .big-next{font-size:1.2rem;color:#bbb}@media(max-width:900px){.v18-suite{grid-template-columns:1fr}.v18-detect{justify-content:flex-start;min-width:0}.v18-form{grid-template-columns:1fr}.v18-list-row{grid-template-columns:1fr}.v18-suite-buttons{max-height:92px;overflow:auto}.editor{max-height:280px}}
